import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_token(token):
    """Verify HMAC-based auth token: username.timestamp.signature"""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None
        username, ts, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), f'{username}.{ts}'.encode(), hashlib.sha256).hexdigest()[:16]
        if hmac.compare_digest(sig, expected):
            return username
    except Exception:
        pass
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role. Requires auth."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    actor = verify_token(auth[7:])
    if not actor:
        return jsonify({'error': 'invalid token'}), 401

    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build query with filters
    query = "SELECT id, username, email, department, role FROM users WHERE 1=1"

    if department:
        query += f" AND department = '{department}'"
    if role:
        query += f" AND role = '{role}'"

    db = get_db()
    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', actor, f'dept={department},role={role}')
        )
        db.commit()

        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    actor = verify_token(auth[7:])
    if not actor:
        return jsonify({'error': 'invalid token'}), 401

    db = get_db()
    user = db.execute(
        "SELECT id, username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()

    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
